// GENERATED by scripts/build-io.mjs from src/ - edit the source, not this file.
// Adding a product to the shopper's real VTEX cart, from inside the page.
//
// The official widget stages the item and hands it to the socket's
// `add_to_cart` frame, which writes the cart server-side with the platform's
// own VTEX credentials. We are injected into the storefront itself, so we go
// straight to the checkout API with the shopper's own session - the same call
// the store's own "add to cart" button makes. It needs no platform-side VTEX
// configuration and the result is the visitor's actual cart, not a copy.
//
// Refreshing the host minicart afterwards is ported from the official widget's
// src/utils/VTEXIOMinicartBridge.js: VTEX IO holds the orderForm in a React
// context, and the only way in from outside React is the Fiber tree.

const MAX_FIBER_DEPTH = 150;
const FIBER_KEY_PREFIXES = ['__reactFiber', '__reactInternalInstance'];
const ROOT_SELECTORS = ['.render-provider', '.render-container', '#render-store-div'];

export interface CartItemRef {
  skuId: string;
  sellerId: string;
}

/**
 * `product_retailer_id` as this project's agents emit it: `243789`,
 * `243789#1` (sku#seller) or `243789#1#4` (sku#seller#tradePolicy). See the
 * format `WeniWebChatCatalog` sends as `retailer_id`.
 */
export function parseRetailerId(retailerId: string, sellerFallback?: string): CartItemRef | null {
  const parts = String(retailerId || '')
    .split('#')
    .map((part) => part.trim());
  const skuId = parts[0];
  if (!skuId) return null;
  // The third segment is the TRADE POLICY, which is not a sales channel:
  // sending it as `?sc=` makes the checkout API answer 500 with an empty body
  // (measured on the Mondelez QA store with `243789#1#4` → sc=4). The session already
  // carries the right sales channel, so the id's third part is not used.
  const sellerId = parts[1] || sellerFallback || '1';
  return { skuId, sellerId };
}

interface OrderFormItem {
  id?: string;
  seller?: string;
  quantity?: number;
  imageUrl?: string;
  imageUrls?: unknown;
  [key: string]: unknown;
}

interface OrderForm {
  orderFormId?: string;
  items?: OrderFormItem[];
  [key: string]: unknown;
}

interface OrderFormContext {
  orderForm?: OrderForm;
  setOrderForm: (orderForm: OrderForm) => void;
}

function fiberKey(node: Element): string | null {
  return Object.keys(node).find((key) => FIBER_KEY_PREFIXES.some((p) => key.startsWith(p))) ?? null;
}

function rootFiber(): any {
  const roots = [
    ...ROOT_SELECTORS.map((selector) => document.querySelector(selector)),
    ...document.querySelectorAll('div, span, section, main'),
  ];
  for (const node of roots) {
    if (!node) continue;
    const key = fiberKey(node);
    if (key) return (node as any)[key] ?? null;
  }
  return null;
}

function isOrderFormContext(value: any): value is OrderFormContext {
  return value != null && typeof value === 'object' && typeof value.setOrderForm === 'function';
}

function contextFromFiber(fiber: any): OrderFormContext | null {
  if (!fiber) return null;
  try {
    if (isOrderFormContext(fiber.memoizedProps?.value)) return fiber.memoizedProps.value;
    for (let hook = fiber.memoizedState; hook; hook = hook.next) {
      if (isOrderFormContext(hook.memoizedState)) return hook.memoizedState;
    }
    for (let ctx = fiber.dependencies?.firstContext; ctx; ctx = ctx.next) {
      if (isOrderFormContext(ctx.memoizedValue)) return ctx.memoizedValue;
    }
  } catch {
    /* a node that refuses inspection is simply not the one */
  }
  return null;
}

function searchDescendants(fiber: any, depth = 0): OrderFormContext | null {
  if (!fiber || depth > MAX_FIBER_DEPTH) return null;
  return (
    contextFromFiber(fiber) ||
    searchDescendants(fiber.child, depth + 1) ||
    searchDescendants(fiber.sibling, depth)
  );
}

/**
 * Pushes the fresh orderForm into whatever the storefront is showing, so the
 * minicart count changes without a reload. Best effort by design: a failure
 * here means a stale badge, never a lost item - the cart itself is already
 * written server-side.
 */
function refreshHostMinicart(orderForm: OrderForm): void {
  try {
    const cart = (window as any).faststore_sdk_stores?.get?.('fs::cart');
    if (cart?.set && cart?.read) {
      cart.set(cart.read());
      return;
    }
  } catch {
    /* FastStore not present - try VTEX IO below */
  }

  try {
    const context = searchDescendants(rootFiber());
    if (!context?.setOrderForm) return;
    // VTEX IO's minicart renders `imageUrls`, which the checkout API doesn't
    // return; reusing what is already on screen avoids a flicker to no image.
    const previous = Object.fromEntries((context.orderForm?.items ?? []).map((item) => [item.id, item]));
    context.setOrderForm({
      ...orderForm,
      items: (orderForm.items ?? []).map((item) => ({
        ...item,
        imageUrls: previous[item.id ?? '']?.imageUrls ?? {
          at1x: item.imageUrl,
          at2x: item.imageUrl,
          at3x: item.imageUrl,
          __typename: 'ImageUrls',
        },
        imageUrl: previous[item.id ?? '']?.imageUrl ?? item.imageUrl,
      })),
    });
  } catch {
    /* not a VTEX IO storefront, or the tree changed shape */
  }
}

/** The visitor's live cart, read with their own cookies. */
async function currentOrderForm(): Promise<OrderForm | null> {
  const response = await fetch('/api/checkout/pub/orderForm', { credentials: 'include' });
  if (!response.ok) return null;
  return (await response.json()) as OrderForm;
}

function lineOf(orderForm: OrderForm, item: CartItemRef): number {
  return (orderForm.items ?? []).findIndex(
    (line) => String(line.id) === item.skuId && (!line.seller || String(line.seller) === item.sellerId),
  );
}

function quantityOf(orderForm: OrderForm, item: CartItemRef): number {
  const index = lineOf(orderForm, item);
  return index > -1 ? Number(orderForm.items?.[index]?.quantity ?? 0) : 0;
}

export class CartError extends Error {}

async function postItems(orderFormId: string, path: 'items' | 'items/update', orderItems: unknown[]): Promise<OrderForm> {
  let response: Response;
  try {
    response = await fetch(`/api/checkout/pub/orderForm/${orderFormId}/${path}`, {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ orderItems }),
    });
  } catch {
    throw new CartError('Não conseguimos adicionar o produto. Verifique sua conexão e tente novamente.');
  }
  if (!response.ok) throw new CartError('Não conseguimos adicionar o produto ao carrinho.');
  try {
    return (await response.json()) as OrderForm;
  } catch {
    throw new CartError('Não conseguimos adicionar o produto ao carrinho.');
  }
}

/**
 * Adds `quantity` units to the shopper's cart and refreshes the storefront's minicart.
 * Throws CartError with a message meant for the visitor.
 */
export async function addProductToCart(item: CartItemRef, quantity = 1): Promise<void> {
  let before: OrderForm | null;
  try {
    before = await currentOrderForm();
  } catch {
    before = null;
  }
  const orderFormId = before?.orderFormId;
  if (!before || !orderFormId) {
    throw new CartError('Não conseguimos abrir seu carrinho. Recarregue a página e tente novamente.');
  }

  // POST /items does NOT add to a line that already exists: measured on this
  // store, adding sku 299 twice leaves it at x1. A product already in the cart
  // gets its quantity raised through /items/update instead.
  const index = lineOf(before, item);
  const had = quantityOf(before, item);
  const orderForm =
    index > -1
      ? await postItems(orderFormId, 'items/update', [{ index, quantity: had + quantity }])
      : await postItems(orderFormId, 'items', [{ id: item.skuId, quantity, seller: item.sellerId }]);

  // VTEX answers 200 with an unchanged cart when the SKU can't be sold in this
  // session (no stock, quantity cap, wrong trade policy), so the quantity in
  // the answer is what actually says whether it worked.
  if (quantityOf(orderForm, item) <= had) {
    throw new CartError(
      had > 0
        ? 'Não foi possível aumentar a quantidade desse produto no carrinho.'
        : 'Esse produto não está disponível no momento.',
    );
  }

  refreshHostMinicart(orderForm);
}

/** The store's own minicart toggle (VTEX IO `vtex.minicart`), most specific first. */
const MINICART_TOGGLES = [
  '.vtex-minicart-2-x-openIconContainer button',
  '[class*="minicart-2-x-openIconContainer"] button',
  '[class*="minicartIconContainer"]',
];

/**
 * Opens the store's cart drawer, the same way the visitor would: by clicking
 * its minicart icon. A storefront without one gets the checkout cart page.
 */
export function openHostCart(): void {
  for (const selector of MINICART_TOGGLES) {
    const toggle = document.querySelector<HTMLElement>(selector);
    if (toggle) {
      toggle.click();
      return;
    }
  }
  window.location.href = '/checkout/#/cart';
}

const MINICART_OPENED = '.vtex-minicart-2-x-opened';

/**
 * Reports whether the store's cart drawer is open, however it was opened.
 * The launcher sits at max z-index (it has to clear the LGPD banner), which
 * would otherwise put it on top of the drawer's totals and checkout button.
 *
 * The drawer is only mounted the first time it opens, so this watches the
 * document rather than the drawer; checks are batched to one per frame.
 */
export function watchHostCart(onChange: (open: boolean) => void): () => void {
  let frame = 0;
  let last: boolean | null = null;
  const report = () => {
    frame = 0;
    const open = Boolean(document.querySelector(MINICART_OPENED));
    if (open !== last) {
      last = open;
      onChange(open);
    }
  };
  const observer = new MutationObserver(() => {
    if (!frame) frame = window.requestAnimationFrame(report);
  });
  observer.observe(document.body, { subtree: true, childList: true, attributes: true, attributeFilter: ['class'] });
  report();
  return () => {
    observer.disconnect();
    window.cancelAnimationFrame(frame);
  };
}
